"""High-level motion planning for RoboTwin-AI."""

from __future__ import annotations

import logging
from dataclasses import dataclass
from enum import Enum

from robot_twin.command.command_interpreter import (
    CommandType,
    RobotCommand,
)


LOGGER = logging.getLogger(__name__)


class MotionDirection(str, Enum):
    """Supported Cartesian motion directions."""

    FORWARD = "forward"
    BACKWARD = "backward"
    LEFT = "left"
    RIGHT = "right"


@dataclass(frozen=True)
class MotionTarget:
    """Target generated by the motion planner."""

    direction: MotionDirection | None = None
    distance: float | None = None
    joint_index: int | None = None
    joint_position: float | None = None


class MotionPlanner:
    """Convert structured commands into robot motion targets."""

    def plan(self, command: RobotCommand) -> MotionTarget:
        """Create a motion target from a structured command."""

        if command.command_type == CommandType.MOVE_JOINT:
            return self._plan_joint_motion(command)

        if command.command_type in {
            CommandType.MOVE_FORWARD,
            CommandType.MOVE_BACKWARD,
            CommandType.MOVE_LEFT,
            CommandType.MOVE_RIGHT,
        }:
            return self._plan_directional_motion(command)

        if command.command_type == CommandType.STOP:
            return MotionTarget()

        raise ValueError(
            f"Unsupported command type: "
            f"{command.command_type.value}"
        )

    def _plan_joint_motion(
        self,
        command: RobotCommand,
    ) -> MotionTarget:
        """Create a joint-space motion target."""

        if command.joint_index is None:
            raise ValueError(
                "Joint motion requires a joint index."
            )

        if command.target_position is None:
            raise ValueError(
                "Joint motion requires a target position."
            )

        LOGGER.info(
            "Planning joint motion: joint=%d target=%.2f degrees",
            command.joint_index,
            command.target_position,
        )

        return MotionTarget(
            joint_index=command.joint_index,
            joint_position=command.target_position,
        )

    def _plan_directional_motion(
        self,
        command: RobotCommand,
    ) -> MotionTarget:
        """Create a Cartesian directional motion target."""

        if command.distance is None:
            raise ValueError(
                "Directional motion requires a distance."
            )

        direction_map = {
            CommandType.MOVE_FORWARD: MotionDirection.FORWARD,
            CommandType.MOVE_BACKWARD: MotionDirection.BACKWARD,
            CommandType.MOVE_LEFT: MotionDirection.LEFT,
            CommandType.MOVE_RIGHT: MotionDirection.RIGHT,
        }

        direction = direction_map.get(
            command.command_type
        )

        if direction is None:
            raise ValueError(
                "Unable to determine motion direction."
            )

        LOGGER.info(
            "Planning directional motion: "
            "direction=%s distance=%.2f m",
            direction.value,
            command.distance,
        )

        return MotionTarget(
            direction=direction,
            distance=command.distance,
        )


def main() -> None:
    """Demonstrate high-level motion planning."""

    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s | %(levelname)s | %(message)s",
    )

    from robot_twin.command.command_interpreter import (
        CommandInterpreter,
    )

    interpreter = CommandInterpreter()
    planner = MotionPlanner()

    commands = (
        "Move joint 2 to 30 degrees",
        "Move forward 2 meters",
        "Go left 1 meter",
        "Stop the robot",
    )

    print()
    print("ROBOTWIN-AI MOTION PLANNER")
    print("=" * 55)

    for text in commands:
        command = interpreter.interpret(text)
        target = planner.plan(command)

        print()
        print(f"Human command : {text}")
        print(f"Robot command : {command}")
        print(f"Motion target : {target}")


if __name__ == "__main__":
    main()